import torch


def _nonzero_int(shape, dtype, device):
    info = torch.iinfo(dtype)
    t = torch.randint(
        info.min, info.max, tuple(shape), dtype=dtype, device="cpu"
    ).to(device)
    return torch.where(t == 0, torch.ones_like(t), t)


def gen_inputs(ctx, device):
    return {
        "input": _nonzero_int(
            ctx["input__shape"], getattr(torch, ctx["input__dtype"]), device
        ),
        "other": _nonzero_int(
            ctx["other__shape"], getattr(torch, ctx["other__dtype"]), device
        ),
    }


def run(input, other):
    return torch.remainder(input, other)
